#include "ros/ros.h"<br>#include "std_msgs/String.h"<br>#include "sensor_msgs/LaserScan.h"<br>#define RAD2DEG(x) ((x)\*180./M_PI)
void scanCallback(const sensor_msgs::LaserScan::ConstPtr&);
int counter=0;
void callback(const ros::TimerEvent&)\{<br>counter++;<br>ROS_INFO("sample file called : %d\\t times",counter);<br>\}
void scanCallback(const sensor_msgs::LaserScan::ConstPtr& scan)\{<br>for(int i=0;i\<360;i++)\{<br>float degree=RAD2DEG(scan-\>angle_min+scan-\>angle_increment\*i);<br>if(scan-\>ranges\[i\]\>0.001)\{<br>printf("\[LIDAR INFO\]\:angle-distance\:\[%4.1f, %5.3f\]\\n", degree,scan-\>ranges\[i\]);<br>\}<br>\}<br>\}
int main(int argc, char \*\*argv)\{<br>ros::init(argc,argv,"listener");
ros::NodeHandle n;
ros::Timer timer1 = n.createTimer(ros::Duration(0.1),callback);
ros::Subscriber sub=n.subscribe\<sensor_msgs::LaserScan\>("/scan",1000,scanCallback);
ros::spin();
return 0;<br>\}
